WoWFA_Data[179057] = "فورانی از انرژی Fel آزاد می‌کنید، $s2 آسیب Chaos وارد می‌کنید و تمام دشمنان نزدیک را به مدت 3 ثانیه استان می‌کنید.$?s320412[\n\nهر دشمنی که با Chaos Nova استان شود، شانس 30% دارد تا یک Lesser Soul Fragment تولید کند.][]"
