WoWFA_Data[452412] = "$?a212612[Eye Beam][Void Ray] اعمال Student of Suffering روی شما می‌کند: به مدت 6 ثانیه تسلط را ${$453239s1*$mas}.1% افزایش داده و هر 2 ثانیه 5 Fury می‌دهد."
WoWFA_En[452413] = "$?a212612[Immolation Aura][Hungering Slash] has $s1 yd increased radius and $s2% increased critical strike damage bonus."
WoWFA_Data[452413] = "$?a212612[Immolation Aura][Hungering Slash] شعاع آن 2 یارد بیشتر و بونوس آسیب Critical Strike آن 50% بیشتر است."
WoWFA_En[452414] = "$?a212612[Agility][Intellect] increased by $?a212612[$452550s1][$452550s2]% while not in demon form.$?c3[\n\nCollapsing Star damage increased by $s2%.][]"
WoWFA_Data[452414] = "$?a212612[Agility][هوش] وقتی در فرم شیطانی نیستید به اندازه‌ی $?a212612[8][10]% افزایش می‌یابد.$?c3[\n\nآسیب Collapsing Star به اندازه‌ی 20% افزایش می‌یابد.][]"
WoWFA_En[452415] = "$?a212612[Activating ][Void ]Metamorphosis greatly empowers $?a212612[Eye Beam and Immolation Aura][The Hunt and casting Collapsing Star resets its cooldown].\n\n$?a212612[Demonsurge][Voidsurge] damage is increased by $?a212612[${$452416s2}][${$1246160s2}]% for each time it previously triggered while your demon form is active."
WoWFA_Data[452415] = "$?a212612[فعال‌کردن ][Void ]Metamorphosis به‌شدت $?a212612[Eye Beam و Immolation Aura را تقویت می‌کند][The Hunt را تقویت می‌کند و اجرای Collapsing Star کول‌داون آن را ریست می‌کند].\n\nآسیب $?a212612[Demonsurge][Voidsurge] به ازای هر بار فعال‌شدن قبلی آن هنگام فعال‌بودن فرم شیطانی، $?a212612[5][10]% افزایش می‌یابد."
WoWFA_Data[471306] = "جمع‌آوری 50 تکه روح به Void Metamorphosis دسترسی می‌دهد.\n\n Void Metamorphosis\n|CFFffffffRequires 50 Soul Fragments|R\n\nYou ascend to a higher state of being, substantially empowering your abilities.\n\nWhile in Void Metamorphosis, your Consume and Reap are enhanced and your Fury will slowly drain. Additionally, Void Ray reduces your Fury drain, deals increased damage, and no longer consumes Fury."
WoWFA_En[473728] = "$?a1217607[][|CFFffffffRequires $c Fury|R]\nUnleash a beam of concentrated void energy, dealing $1213649s1 Cosmic damage$?a1217607[][ and consuming $1213649c Fury] every ${$t1}.1 sec.$?a1217607[\n\nChanneling Void Ray substantially reduces your Fury drain.][\n\nEffect ends after $d or upon reaching $s4 Fury.]"
WoWFA_Data[473728] = "$?a1217607[][|CFFffffffنیازمند $c Fury|R]\nپرتویی از انرژی Void متمرکز آزاد می‌کنید که هر 0.1 ثانیه $1213649s1 آسیب Cosmic وارد می‌کند$?a1217607[][ و $1213649c Fury مصرف می‌کند].$?a1217607[\n\nکانال کردن Void Ray تخلیه‌ی Fury شما را به‌طور قابل‌توجهی کاهش می‌دهد.][\n\nاثر پس از 3 ثانیه یا با رسیدن به $s4 Fury پایان می‌یابد.]"
WoWFA_Data[1215617] = "آسیب Consume به اندازه‌ی 15% افزایش می‌یابد.\n\nConsume یک تکه روح تولید می‌کند."
WoWFA_Data[1220506] = "Blade Dance به‌صورت خودکار روی هدف اصلی شما Throw Glaive را با 100% آسیب فعال می‌کند و هر برش شانس 50% دارد تا با 35% آسیب روی دشمنی Throw Glaive اجرا کند."
WoWFA_En[1221167] = "While in Void Metamorphosis, every $s1 Soul Fragments harvested grants access to Collapsing Star.\n\n$@spellicon1221150 $@spellname1221150\n$@spelldesc1221150"
WoWFA_Data[1221167] = "در حین Void Metamorphosis، هر 30 روحِ درو‌شده به Collapsing Star دسترسی می‌دهد.\n\n Collapsing Star\nChannel an immense amount of void energy into a single, cataclysmic blast, $?a1242486[critically striking for ${$1221162s1*2}][dealing $1221162s1] Cosmic damage to your target and $?a1242486[${2*($1221162s1*($s2/100))}][${$1221162s1*($s2/100)}] Cosmic damage to all nearby enemies. Damage reduced beyond 8 targets.\n\nWhile casting Collapsing Star, your Fury drain is significantly reduced.$?a1240204[\n\n|CFFffffffGenerates 3 Soul $LFragment:Fragments;|R.][]"
WoWFA_Data[1223171] = "برد اجرای Voidblade، Consume Magic و Disrupt به اندازه‌ی 20 یارد افزایش می‌یابد."
WoWFA_Data[1223918] = "آسیب Void Ray شانس 200% بیشتری برای تولید تکه روح دارد."
WoWFA_En[1226033] = "Fully channeling Void Ray upgrades your Reap to Eradicate.\n\n$@spellicon1225826 $@spellname1225826\n$@spelldesc1225826"
WoWFA_Data[1226033] = "کانال کردن کامل Void Ray، Reap شما را به Eradicate ارتقا می‌دهد.\n\n Eradicate\nSlam your Scythe to the ground, dealing $?a1217607[$1279200s1][$1225827s1] Cosmic damage to your primary target and $?a1217607[${$1279200s1*($s1/100)}][${$1225827s1*($s1/100)}] to all other enemies within a 25 yd cone in front of you. Damage reduced beyond 5 targets.\n\nEradicate gathers up to 4 nearby souls.$?a1246558[\n\n|CFFffffffGenerates 10 Fury.|R][]"
WoWFA_Data[1227707] = "هر Collapsing Star که اجرا می‌کنید، آسیب Collapsing Star بعدی شما را 20% افزایش می‌دهد."
WoWFA_En[1234195] = "Unleash an eruption of void energy, dealing $s2 Cosmic damage and stunning your target and all nearby enemies for $d."
WoWFA_Data[1234195] = "فورانی از انرژی Void آزاد می‌کنید، $s2 آسیب Cosmic وارد می‌کنید و هدف خود و تمام دشمنان نزدیک را به مدت 2 ثانیه استان می‌کنید."
WoWFA_Data[1237270] = "تکه روح‌ها به مدت 6 ثانیه مقدار 1% آسیب بیشتر می‌دهند. چند اعمال‌شدن می‌توانند هم‌پوشانی داشته باشند."
WoWFA_Data[1238488] = "پس از کانال کردن کامل Void Ray، کول‌داون Reap ریست می‌شود و Reap بعدی شما تا 6 تکه روح اضافی جمع می‌کند."
WoWFA_Data[1238739] = "هر تکه روحی که Reap جمع می‌کند، آسیب آن را 8% افزایش می‌دهد."
WoWFA_En[1239519] = "After dealing damage with The Hunt or Voidblade, Voidblade is replaced with Hungering Slash for $1239525d.\n\n$@spellicon1239123 $@spellname1239123\n$@spelldesc1239123\n\nHungering Slash grants a temporary charge of Vengeful Retreat and causes your next Vengeful Retreat within $1223157d to deal an additional $1239526s1 Cosmic damage."
WoWFA_Data[1239519] = "پس از وارد‌کردن آسیب با The Hunt یا Voidblade، Voidblade به مدت 6 ثانیه با Hungering Slash جایگزین می‌شود.\n\n Hungering Slash\nViolently slash your scythe around you, dealing $1239127s1 Cosmic damage to nearby enemies and generating 10 Fury. Shatters up to 2 Soul $LFragment:Fragments; from nearby enemies. Damage reduced beyond 8 targets.\n\nHungering Slash یک شارژ موقت Vengeful Retreat می‌دهد و باعث می‌شود Vengeful Retreat بعدی شما در بازه‌ی 6 ثانیه مقدار $1239526s1 آسیب Cosmic اضافی وارد کند."
WoWFA_Data[1239537] = "Reap یک شارژ اضافی به دست می‌آورد."
WoWFA_Data[1240201] = "آسیب Voidblade و the Hunt، آسیبی که هدف شما از شما می‌گیرد را به مدت 10 ثانیه به اندازه‌ی 12% افزایش می‌دهد. چند اعمال‌شدن می‌توانند هم‌پوشانی داشته باشند."
WoWFA_Data[1240202] = "پس از کانال کردن کامل Void Ray، مقدار 10 Fury می‌گیرید."
WoWFA_Data[1240203] = "Void Ray وقتی به 3 هدف آسیب بزند 80% آسیب بیشتری وارد می‌کند."
WoWFA_Data[1240204] = "Collapsing Star حالا 3 تکه روح تولید می‌کند."
WoWFA_Data[1241937] = "روح خود را شعله‌ور می‌کنید: به اندازه‌ی 24% از حداکثر سلامتی خود شفا می‌گیرید، 30 Fury تولید کرده و در طول 5 ثانیه مقدار 3 تکه روح می‌شکنید."
WoWFA_Data[1242486] = "Collapsing Star همیشه Critical Strike می‌زند."
WoWFA_Data[1242492] = "هر روحی که در Void Metamorphosis مصرف می‌شود 0.25% سرعت می‌دهد، تا سقف 25%."
WoWFA_Data[1242495] = "Critical Strikeهای آسیب‌دهنده‌ی شما به‌جای 200% معمول، 240% آسیب وارد می‌کنند."
WoWFA_Data[1242768] = "شانس شما برای شکستن تکه روح از دشمنانی که به آن‌ها آسیب می‌زنید 2% افزایش می‌یابد."
WoWFA_Data[1242956] = "تسلط شما 2% افزایش می‌یابد."
WoWFA_Data[1244220] = "کول‌داون Void Ray در حین Void Metamorphosis به اندازه‌ی 2.5 ثانیه کاهش می‌یابد."
WoWFA_Data[1244222] = "آسیب Reap و Consume به اندازه‌ی 10% افزایش می‌یابد."
WoWFA_Data[1244237] = "وقتی Void Metamorphosis تمام می‌شود، به ازای هر روحِ استفاده‌نشده‌ای که درو کرده‌اید، 5 Fury گرفته و به مدت 12 ثانیه آسیب خود را 0.5% افزایش می‌دهید."
WoWFA_Data[1244295] = "مدت Feast of Souls به اندازه‌ی 1 ثانیه افزایش می‌یابد.\n\n Feast of Souls\nتکه روح‌ها به مدت 6 ثانیه مقدار 1% آسیب بیشتر می‌دهند. چند اعمال‌شدن می‌توانند هم‌پوشانی داشته باشند."
WoWFA_En[1244557] = "The final slash of Blade Dance consumes $s1 Fury when it strikes $s2 or more enemies, launching two demonic glaives in a whirlwind of energy, causing ${14*$342857s1} Chaos damage over $342817d to all nearby enemies. Deals reduced damage beyond $342817s2 targets."
WoWFA_Data[1244557] = "برش آخر Blade Dance وقتی به 3 دشمن یا بیشتر اصابت کند 25 Fury مصرف می‌کند و دو گلاو شیطانی را در گردابی از انرژی رها می‌کند که در طول 3 ثانیه به تمام دشمنان نزدیک ${14*$342857s1} آسیب Chaos وارد می‌کند. آسیب پس از 8 هدف کاهش می‌یابد."
WoWFA_En[1245412] = "Unleash your glaives and charge to your target, dealing $1245414s2 Cosmic damage.$?a1246562[\n\n|CFFffffffGenerates $1245414s3 Fury.|R][]\n"
WoWFA_Data[1245412] = "گلاوهای خود را رها می‌کنید، به سمت هدف خود یورش می‌کنید و $1245414s2 آسیب Cosmic وارد می‌کنید.$?a1246562[\n\n|CFFffffff$1245414s3 Fury تولید می‌کند.|R][]"
WoWFA_En[1246167] = "Charge to your target, striking them for $1246169s1 Cosmic damage, rooting them in place for $370970d and inflicting $1246168o1 Cosmic damage over $1246168d to up to $370967s2 enemies in your path."
WoWFA_Data[1246167] = "به سمت هدف خود یورش می‌کنید، $1246169s1 آسیب Cosmic به او وارد می‌کنید، او را به مدت 1.5 ثانیه زمین‌گیر می‌کنید و در مسیر خود به حداکثر 5 دشمن در طول 6 ثانیه مقدار $1246168o1 آسیب Cosmic وارد می‌کنید."
WoWFA_Data[1246555] = "کول‌داون Soul Immolation به اندازه‌ی 30 ثانیه کاهش می‌یابد و 1 شارژ اضافی به دست می‌آورد."
WoWFA_Data[1246556] = "Soul Immolation در طول مدت خود مقدار 6% اضافی از سلامتی شما شفا می‌دهد و کول‌داونش با کشتن دشمنی که تجربه یا افتخار می‌دهد ریست می‌شود."
WoWFA_Data[1246558] = "Reap حالا 10 Fury تولید می‌کند."
WoWFA_Data[1246562] = "آسیب Voidblade به اندازه‌ی 100% افزایش می‌یابد و Voidblade حالا 20 Fury تولید می‌کند."
WoWFA_Data[1247534] = "Void Metamorphosis به 15 روح کمتری نیاز دارد.\n\nFury شما در حین Void Metamorphosis مقدار 25% سریع‌تر تخلیه می‌شود."
WoWFA_Data[1247538] = "آسیب Void Ray و Hungering Slash به اندازه‌ی 10% افزایش می‌یابد."
WoWFA_Data[1250088] = "تمام آسیب Cosmic واردشده 3% افزایش می‌یابد.\n\nآسیب Critical Strike Collapsing Star به اندازه‌ی 50% از شانس Critical Strike شما افزایش می‌یابد."
WoWFA_Data[1250094] = "وارد‌شدن به Void Metamorphosis باعث فوران روح شما می‌شود: 5 تکه روح تولید کرده و دسترسی فوری به Collapsing Star می‌دهد."
WoWFA_En[1253304] = "$?a212613[Fracture][Consume] has a $s3% chance to grant $m1 $Lstack:stacks; of Voidfall.\n\nUpon reaching $1256301u stacks of Voidfall, $?a212613[Soul Cleave][Reap] consumes a stack to reach into the Void and call down a meteor strike at your target's location, dealing $?a212613[$1256306s1 Shadowflame][$1256305s1 Cosmic] damage to all enemies within $1256306A yards. Damage reduced beyond $s2 targets."
WoWFA_Data[1253304] = "$?a212613[Fracture][Consume] شانس 35% دارد تا 1 استک از Voidfall بدهد.\n\nبا رسیدن به 3 لایه Voidfall، $?a212613[Soul Cleave][Reap] یک لایه مصرف می‌کند، دست به درون Void دراز می‌کند و در مکان هدف شما ضربه‌ی شهاب فرامی‌خواند که به تمام دشمنان در شعاع 8 یارد $?a212613[$1256306s1 آسیب Shadowflame][$1256305s1 آسیب Cosmic] وارد می‌کند. آسیب پس از 8 هدف کاهش می‌یابد."
WoWFA_En[1253377] = "$?c2[Fel Devastation][Void Ray] damage increased by $s1%.\n\n$?c2[Fel Devastation][Fully channeling Void Ray] generates $?c2[$s4 Soul Fragments over its duration][$s3 $Lstack:stacks; of Voidfall]."
WoWFA_Data[1253377] = "آسیب $?c2[Fel Devastation][Void Ray] به اندازه‌ی 15% افزایش می‌یابد.\n\n$?c2[Fel Devastation][کانال کردن کامل Void Ray] مقدار $?c2[3 تکه روح در طول مدت خود][1 استک از Voidfall] تولید می‌کند."
WoWFA_En[1253391] = "While at $s1 stacks of Voidfall, $?c2[Spirit Bomb and Soul Cleave][Reap] consumes all $s1 to rapidly call down that many meteor strikes."
WoWFA_Data[1253391] = "وقتی 3 لایه Voidfall دارید، $?c2[Spirit Bomb و Soul Cleave][Reap] هر 3 لایه را مصرف کرده و به همان تعداد، به‌سرعت ضربه‌ی شهاب فرامی‌خواند."
WoWFA_Data[1253399] = "هر لایه Voidfall مقدار 3% سرعت حرکت می‌دهد."
WoWFA_En[1253402] = "$?a212613[Torment][Shift] has $m1 additional $Lcharge:charges;."
WoWFA_Data[1253402] = "$?a212613[Torment][Shift] تعداد 1 شارژ اضافی دارد."
WoWFA_En[1253415] = "$?s263642[Fracture]?a212613[Shear][Consume] generates $?a212613[$s1][$s2] additional Fury and deals $?a212613[$s3%][$s4%] increased damage."
WoWFA_Data[1253415] = "$?s263642[Fracture]?a212613[Shear][Consume] مقدار $?a212613[3][2] Fury اضافی تولید کرده و $?a212613[25%][15%] آسیب بیشتر وارد می‌کند."
WoWFA_Data[1253668] = "هر لایه Voidfall مقدار 2% سرعت می‌دهد."
WoWFA_En[1253676] = "Activating $?a212613[Infernal Strike][Void Ray] out of combat or within $?a1213636[${$1265768d*$s2} sec][$1265768d] of entering combat calls down $?a212613[$s3][$s1] Voidfall $LMeteor:Meteors;$?a212613[][ over its duration]."
WoWFA_Data[1253676] = "فعال‌کردن $?a212613[Infernal Strike][Void Ray] خارج از حالت مبارزه یا در بازه‌ی $?a1213636[10 ثانیه][5 ثانیه] پس از شروع مبارزه، تعداد $?a212613[1][3] شهاب از Voidfall$?a212613[][ در طول مدت آن] را فرامی‌خواند."
WoWFA_En[1253769] = "Enemies struck by a Voidfall Meteor take an additional $?a212613[$s1%][$s2%] damage over $1256667d."
WoWFA_Data[1253769] = "دشمنانی که با Voidfall Meteor اصابت می‌کنند، در طول 8 ثانیه مقدار $?a212613[25%][25%] آسیب اضافی می‌گیرند."
WoWFA_Data[1253805] = "بونوس‌های غیرفعالِ هر لایه Voidfall پس از مصرف‌شدن، به مدت 8 ثانیه باقی می‌مانند."
WoWFA_En[1253817] = "$?a212613[Spirit Bomb][Collapsing Star] and Voidfall meteors deal $?a212613[$s1][$s3]% increased damage when striking a single target.\n\nEach additional target reduces this bonus by $s2%."
WoWFA_Data[1253817] = "$?a212613[Spirit Bomb][Collapsing Star] و شهاب‌های Voidfall وقتی فقط به یک هدف اصابت کنند $?a212613[35][30]% آسیب بیشتر وارد می‌کنند.\n\nهر هدف اضافی این بونوس را 5% کاهش می‌دهد."
WoWFA_Data[1256245] = "هر لایه Voidfall مقدار 2% کاهش آسیب دریافتی می‌دهد."
WoWFA_En[1256295] = "Gain $m1 $Lstack:stacks; of Voidfall $?a212613[and reset the cooldown of Spirit Bomb][and reset the cooldown of Reap] upon activating $?a212613[Metamorphosis][Void Metamorphosis]."
WoWFA_Data[1256295] = "هنگام فعال‌کردن $?a212613[Metamorphosis][Void Metamorphosis]، تعداد 3 استک از Voidfall می‌گیرید و $?a212613[کول‌داون Spirit Bomb][کول‌داون Reap] ریست می‌شود."
WoWFA_En[1256307] = "Your first $?a212613[Spirit Bomb][Collapsing Star] after $?a212613[entering demon form][casting Void Metamorphosis] causes a $?a212613[Shadowflame][Cosmic] meteor shower to assault the area, dealing $?a212613[${$1264130s1*($s1)} Shadowflame][${$1264129s1*($s1)} Cosmic] damage over ${$s1/2} sec."
WoWFA_Data[1256307] = "اولین $?a212613[Spirit Bomb][Collapsing Star] شما پس از $?a212613[وارد‌شدن به فرم شیطانی][اجرای Void Metamorphosis] بارانی از شهاب‌های $?a212613[Shadowflame][Cosmic] را بر منطقه می‌فرستد که در طول 6 ثانیه $?a212613[${$1264130s1*($s1)} آسیب Shadowflame][${$1264129s1*($s1)} آسیب Cosmic] وارد می‌کند."
WoWFA_En[1256353] = "The third Voidfall meteor strike called down in sequence is larger, has $s1% increased area, deals $s2% increased damage, and $?a212613[reduces the remaining cooldown of Metamorphosis by $s3 sec][generates $s4 Soul $LFragment:Fragments;]."
WoWFA_Data[1256353] = "سومین ضربه‌ی شهاب Voidfall که پشت‌سرهم فرامی‌آید بزرگ‌تر است، 50% شعاع بیشتری دارد، 50% آسیب بیشتری وارد می‌کند و $?a212613[کول‌داون باقی‌مانده‌ی Metamorphosis را 10 ثانیه کاهش می‌دهد][1 تکه روح تولید می‌کند]."
WoWFA_Data[1261684] = "در حالت مبارزه، هر 12 ثانیه 1 تکه روح تولید می‌کنید.\n\nخارج از مبارزه، به‌تدریج به سمت Void Metamorphosis خود پیش می‌روید، تا سقف 25 تکه روح."
WoWFA_Data[1265800] = "آسیب Physical به اندازه‌ی 12% افزایش می‌یابد."
WoWFA_Data[1265818] = "Metamorphosis به اندازه‌ی 5 ثانیه مدت بیشتری دارد و آسیب Fracture، Soul Cleave و Spirit Bomb را 20% افزایش می‌دهد."
WoWFA_En[1265924] = "Spirit Bomb shields you for $263648d, absorbing ${$MHP*$s1/100} damage plus ${$MHP*$s2/100} for each Soul Fragment consumed."
