WoWFA_Data[1266328] = "حمله‌ها و قابلیت‌هایی که Fury مصرف می‌کنند 3% آسیب بیشتر وارد می‌کنند."
WoWFA_Data[1266329] = "قطع کردن یک جادو با Disrupt، آسیب جادویی دریافتی شما را به مدت 12 ثانیه به اندازه‌ی 15% کاهش می‌دهد."
WoWFA_Data[1266330] = "هر بار که در شرف تولید یک یا چند تکه روح هستید، شانس 2% دارید تا یک تکه روح اضافی تولید کنید."
WoWFA_Data[1266493] = "سرعت سُرخوردن (Glide) به اندازه‌ی 10% افزایش می‌یابد."
